// Des: Tests the neutral to MySQL statement translation
// Flo: build statements both ways > compare text
// I/O: statements > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const sqlz = @import("sy-clou-sqlz.zig"); const xlat = @import("sy-mirr-xlat.zig");
fn arenNewz() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
fn both(aren: std.mem.Allocator, texz: []const u8, hexz: []const u8) !void { const colz = [_]sqlz.Colz{ .{ .name = "urlh", .valu = try sqlz.litz(aren, .sqlt, hexz) }, .{ .name = "body", .valu = try sqlz.litz(aren, .sqlt, texz) }, .{ .name = "timz", .valu = "12" } }; const colm = [_]sqlz.Colz{ .{ .name = "urlh", .valu = try sqlz.litz(aren, .mysq, hexz) }, .{ .name = "body", .valu = try sqlz.litz(aren, .mysq, texz) }, .{ .name = "timz", .valu = "12" } }; const neut = try sqlz.upse(aren, .sqlt, "cl_reco", "urlh", &colz); const want = try sqlz.upse(aren, .mysq, "cl_reco", "urlh", &colm); try std.testing.expectEqualStrings(want, try xlat.mysqOfzz(aren, neut)); try std.testing.expectEqualStrings(neut, try xlat.forzDial(aren, .pgsq, neut)); try std.testing.expectEqualStrings(neut, try xlat.forzDial(aren, .sqlt, neut)); }
test "an upsert in neutral form becomes byte for byte the MySQL upsert, for plain, quoted and backslash text" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); try both(allo, "hello", "ab12"); try both(allo, "it's a 'quoted' text", "ab12"); try both(allo, "C:\\path\\to\\file \\n end\\", "ab12"); try both(allo, "body with ON CONFLICT(x) DO UPDATE SET a=excluded.a inside", "ab12"); try both(allo, "tiếng Việt có dấu \\ và ''", "ab12"); try both(allo, "", "ab12"); }
test "a delete and an update keep their text, only backslashes inside quotes change" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); try std.testing.expectEqualStrings("DELETE FROM cl_manif WHERE pack='runs/a\\\\b'", try xlat.mysqOfzz(allo, "DELETE FROM cl_manif WHERE pack='runs/a\\b'")); try std.testing.expectEqualStrings("UPDATE cl_reco SET body='' WHERE urlh IN ('a','b')", try xlat.mysqOfzz(allo, "UPDATE cl_reco SET body='' WHERE urlh IN ('a','b')")); try std.testing.expectEqualStrings("CREATE TABLE IF NOT EXISTS cl_purg(packz VARCHAR(200) PRIMARY KEY, timz BIGINT, ents INT)", try xlat.mysqOfzz(allo, "CREATE TABLE IF NOT EXISTS cl_purg(packz VARCHAR(200) PRIMARY KEY, timz BIGINT, ents INT)")); }
test "every statement the sync writes survives the round trip, a broken tail is refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); const list = try xlat.listDial(allo, .mysq, &sqlz.DDL); try std.testing.expectEqual(@as(usize, 4), list.len); try std.testing.expectEqualStrings(sqlz.DDL[0], list[0]); try std.testing.expectError(error.BadStmt, xlat.mysqOfzz(allo, "INSERT INTO t(a) VALUES(1) ON CONFLICT(a) DO NOTHING")); const same = try xlat.listDial(allo, .sqlt, &sqlz.DDL); try std.testing.expectEqual(@intFromPtr(&sqlz.DDL), @intFromPtr(same.ptr)); }
